import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    orders_info = {}  # id -> dict(side, price, qty, active)
    seq_counter = 0

    def clean_heap(heap):
        while heap:
            price_key, seq, oid = heap[0]
            info = orders_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(heap)
            else:
                break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = orders_info.get(oid)
            if info is not None:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        seq = seq_counter
        seq_counter += 1

        orders_info[oid] = {'side': side, 'price': price, 'qty': remaining, 'active': True}

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0:
            clean_heap(opp_heap)
            if not opp_heap:
                break
            top_price_key, top_seq, top_id = opp_heap[0]
            top_info = orders_info[top_id]
            resting_price = top_info['price']

            if side == 'buy':
                if price is not None and resting_price > price:
                    break
            else:
                if price is not None and resting_price < price:
                    break

            resting_qty = top_info['qty']
            trade_qty = min(remaining, resting_qty)

            if side == 'buy':
                trades.append([oid, top_id, resting_price, trade_qty])
            else:
                trades.append([top_id, oid, resting_price, trade_qty])

            remaining -= trade_qty
            top_info['qty'] -= trade_qty
            orders_info[oid]['qty'] = remaining

            if top_info['qty'] <= 0:
                top_info['active'] = False
                heapq.heappop(opp_heap)

        orders_info[oid]['qty'] = remaining

        if typ == 'limit' and remaining > 0:
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq, oid))
            else:
                heapq.heappush(sell_heap, (price, seq, oid))
        else:
            orders_info[oid]['active'] = False

    return trades

